  if (nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => v < 1 || v > 1000000)) return 'Each value is between 1 and 10^6.';
  if (k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
