function minSubarraySort(nums, k) {
  const result = [];
  for (let start = 0; start + k <= nums.length; start++) {
    const end = start + k - 1;
    let right = -1;
    let maxSoFar = nums[start];
    for (let i = start + 1; i <= end; i++) {
      if (nums[i] < maxSoFar) {
        right = i;
      } else {
        maxSoFar = nums[i];
      }
    }
    if (right === -1) {
      result.push(0);
      continue;
    }
    let left = end;
    let minSoFar = nums[end];
    for (let i = end - 1; i >= start; i--) {
      if (nums[i] > minSoFar) {
        left = i;
      } else {
        minSoFar = nums[i];
      }
    }
    result.push(right - left + 1);
  }
  return result;
}

