function minSubarraySort(nums, k) {
  const result = [];
  for (let start = 0; start + k <= nums.length; start++) {
    const window = nums.slice(start, start + k);
    const sorted = [...window].sort((a, b) => a - b);
    let first = 0;
    while (first < k && window[first] === sorted[first]) first++;
    if (first === k) { result.push(0); continue; }
    let last = k - 1;
    while (window[last] === sorted[last]) last--;
    result.push(last - first + 1);
  }
  return result;
}

