function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(900, 1000) : int(1, 8);
  const top = size === 'large' ? 1000000 : int(1, 6);
  const nums = Array.from({ length: n }, () => int(1, top));
  if (rand() < 0.6) {
    // Mostly sorted with a few nearby swaps, so windows range from sorted to badly broken.
    nums.sort((a, b) => a - b);
    const swaps = int(0, Math.max(1, Math.floor(n / 25)));
    for (let s = 0; s < swaps; s++) {
      const a = int(0, n - 1), b = Math.min(n - 1, a + int(1, 12));
      [nums[a], nums[b]] = [nums[b], nums[a]];
    }
  }
  // Half the time use a short window, so sorted and unsorted windows mix.
  return [nums, rand() < 0.5 ? int(1, Math.min(n, 30)) : int(1, n)];
}
